import { expect, expectStatus, sample, test, uniqueName, type Document, type Extraction, type Vendor } from "../../fixtures";
import { readFileSync } from "node:fs";

test.describe("vendor lifecycle", () => {
  test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }) => {
    // Arrange: a vendor in review whose insurance certificate expires today.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const vendor = await factory.vendor({ name: uniqueName("Expiring Cert") });

    const today = new Date().toISOString().slice(0, 10);
    const certificate = `Insurer: Harbor Mutual\nPolicy Number: HM-55-${Date.now().toString(36)}\nCoverage Amount: $2,000,000\nExpiry Date: ${today}\n`;

    const uploads = [
      await factory.upload(vendor.id, "w9"),
      await factory.upload(vendor.id, "contract"),
      await expectStatus<Document>(
        await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: { name: "insurance_certificate_expiring.txt", mimeType: "text/plain", buffer: Buffer.from(certificate) },
          },
        }),
        201,
      ),
    ];
    const insuranceId = uploads[2].id;

    await expect
      .poll(
        async () => {
          const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
          return docs.map((d) => d.status).sort();
        },
        { message: "extraction finishes for all three documents", timeout: 30_000 },
      )
      .toEqual(["extracted", "extracted", "extracted"]);

    await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
    const pending: Extraction = await factory.extraction(insuranceId, "member");
    expect(pending.status, "insurance extraction awaits review").toBe("pending_review");
    const extractionId = pending.id;

    // Act: the reviewer approves the insurance certificate extraction.
    const response = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
      data: { decision: "approve" },
    });

    // Assert: the response and the stored extraction both show approval.
    const body = await expectStatus<Extraction>(response, 200);
    expect(body.status).toBe("approved");

    const stored = await factory.extraction(insuranceId, "reviewer");
    expect(stored.status, "approval is stored, not just echoed").toBe("approved");
  });
});

